using System.Text; using FluentValidation; using CRN.ProductApi.Application.Interfaces; using CRN.ProductApi.Application.Mapping; using CRN.ProductApi.Application.Services; using CRN.ProductApi.Infrastructure.Data; using CRN.ProductApi.Infrastructure.Data.Repositories; using CRN.ProductApi.Infrastructure.Identity; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens;
namespace CRN.ProductApi.Extensions;
public static class ServiceExtensions
{
 public static IServiceCollection AddProjectServices(this IServiceCollection services,IConfiguration config){services.AddDbContext<ApplicationDbContext>(o=>o.UseSqlServer(config.GetConnectionString("DefaultConnection")));services.AddAutoMapper(typeof(MappingProfile).Assembly);services.AddScoped<IProductRepository,ProductRepository>();services.AddScoped<IProductService,ProductService>();services.AddScoped<IUnitOfWork,UnitOfWork>();services.AddScoped<IJwtService,JwtService>();services.AddScoped<IAuthService,AuthService>();services.AddValidatorsFromAssemblyContaining<CRN.ProductApi.Application.Validators.CreateProductValidator>();var jwt=config.GetSection("Jwt");var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt["Key"]!));services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>{o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidIssuer=jwt["Issuer"],ValidateAudience=true,ValidAudience=jwt["Audience"],ValidateIssuerSigningKey=true,IssuerSigningKey=key,ValidateLifetime=true,ClockSkew=TimeSpan.FromMinutes(1)};});services.AddAuthorization();return services;}
}
